think.q:
This debounce looks fine at first glance. What is wrong with it?<pre><code>function debounce(fn, delay) {
  return (...args) => {
    setTimeout(() => fn(...args), delay)
  }
}</code></pre>

checks.test:
const d = debounce(console.log, 300)
d(1); d(2); d(3)
// expected: prints once, about 300ms later

d(1)
setTimeout(() => d(2), 200)
// expected: prints 2 at about 500ms, not at 300ms

const o = { n: 7, hi: debounce(function () { console.log(this.n) }, 100) }
o.hi()
// expected: prints 7

const d = debounce(console.log, 300, { leading: true })
d(1); d(2)
// expected: prints 1 immediately, and 2 does not fire immediately

problems.solution:
function debounce(fn, delay, { leading = false } = {}) {
  let timer = null

  function debounced(...args) {
    const ctx = this
    const callNow = leading && timer === null

    clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      if (!leading) fn.apply(ctx, args)
    }, delay)

    if (callNow) fn.apply(ctx, args)
  }

  debounced.cancel = () => {
    clearTimeout(timer)
    timer = null
  }
  return debounced
}

think.q:
What is wrong with this implementation?
<pre><code>function throttle(fn, delay) {
  return (...args) => {
    setTimeout(() => fn(...args), delay)
  }
}</code></pre>

problems.solution:
function throttle(fn, delay) {
  let lastCall = -Infinity
  let timer = null
  let args = null
  let context = null

  function throttled(...nextArgs) {
    const now = Date.now()
    args = nextArgs
    context = this
    const remaining = delay - (now - lastCall)

    if (remaining <= 0) {
      clearTimeout(timer)
      timer = null
      const callArgs = args
      const callContext = context
      args = context = null
      lastCall = now
      fn.apply(callContext, callArgs)
    } else if (timer === null) {
      timer = setTimeout(() => {
        timer = null
        if (args !== null) {
          const callArgs = args
          const callContext = context
          args = context = null
          lastCall = Date.now()
          fn.apply(callContext, callArgs)
        }
      }, remaining)
    }
  }

  throttled.cancel = () => {
    clearTimeout(timer)
    timer = null
    args = context = null
    lastCall = -Infinity
  }
  return throttled
}

think.q:
Why does this implementation fail for partial application?
<pre><code>const curry = fn =&gt; (...args) =&gt; {
  if (args.length &gt;= fn.length) return fn(...args);
  return curry(fn.bind(null, ...args));
};</code></pre>

What is <code>fn.length</code> for this function?
<pre><code>function example(a, b = 10, c) {
  return a + b + c;
}</code></pre>

problems.pseudo:
curry(fn):
  requiredCount = original function's declared arity

  create collect(previousArguments):
    return a function accepting new arguments
      combine previous and new arguments in order
      if combined count is at least requiredCount:
        call the original function with combined arguments
      otherwise:
        return collect(combined arguments)

  return collect(no arguments)

problems.solution:
function curry(fn) {
  const arity = fn.length

  function collect(collected) {
    if (collected.length >= arity) return fn(...collected)
    return function (...next) {
      return collect([...collected, ...next])
    }
  }

  return arity === 0 ? (...args) => fn(...args) : collect([])
}

function memoize(fn, resolver) {
  const cache = new Map()

  function memoized(...args) {
    const key = resolver ? resolver(...args) : JSON.stringify(args)
    if (cache.has(key)) return cache.get(key)
    const result = fn.apply(this, args)
    cache.set(key, result)
    return result
  }

  memoized.cache = cache
  memoized.clear = () => cache.clear()
  return memoized
}

function pipe(...fns) {
  return value => fns.reduce((current, fn) => fn(current), value)
}

function compose(...fns) {
  return value => fns.reduceRight((current, fn) => fn(current), value)
}

function pipeAsync(...fns) {
  return async value => {
    let current = value
    for (const fn of fns) current = await fn(current)
    return current
  }
}

think.q:
What is wrong with this implementation?
<pre><code>function flatten(arr) {
  return arr.reduce((out, item) =&gt; out.concat(item), []);
}</code></pre>

problems.solution:
function flatten(arr, depth = Infinity) {
  const limit = depth === Infinity ? Infinity : Math.max(0, Math.trunc(Number(depth) || 0))
  const result = []

  function visit(items, remaining) {
    for (let i = 0; i < items.length; i++) {
      if (!(i in items)) continue
      const item = items[i]
      if (Array.isArray(item) && remaining > 0) {
        visit(item, remaining === Infinity ? Infinity : remaining - 1)
      } else {
        result.push(item)
      }
    }
  }

  visit(arr, limit)
  return result
}
